-- Workspace/Mapa/Zonas. `name` é o texto exibido (inglês). `centroX`/`meiaLargura` = área jogável
-- (Z centrado em 0); o ZonaSystem lê o mesmo do `Chao` invisível de cada Model, a grade de alturas
-- está em Shared/Mapa/Alturas. Zonas a 4000 studs no X para não se verem. Adendo 2: 900×900 (Santuário 480×480).
-- Inimigos ninja (2026-10-30): guardiões/mini-chefes novos; o Santuário tem `chefeFinal` (Sealed Demon).

export type ZonaDef = {
	id: string,
	name: string,
	guardiao: string, -- chave em Definicoes/Chefes
	miniChefe: string, -- chave em Definicoes/Chefes (ehMini), aparece aos Config.MiniChefeTempo (Mobs 2026-10-30)
	multHp: number, -- multiplicador de vida dos inimigos comuns e do chefe
	centroX: number,
	meiaLargura: number,
	final: boolean?,
	chefeFinal: string?, -- Inimigos ninja: chave em Definicoes/Chefes que aparece quando o guardião cai (zona final)
	-- Lote da HUD (2026-10-30): retângulos de água (Parts "Agua" da zona: centro, tamanho X/Z, giro Y em graus) pro mapa.
	-- Polimento UI v2 (2026-10-30): PNG do mapa da zona (1024², cobre centroX±meiaLargura × ±meiaLargura; +X à direita,
